"""
AgroPulse Global Benchmark Soil Series & Pedological Horizon Database.
Synthesized according to USDA Soil Taxonomy and FAO-WRB classification.
Provides horizon-by-horizon physical, chemical, hydraulic, and pedotransfer functions.
"""

from typing import Dict, List, Optional
from pydantic import BaseModel, Field


class SoilHorizonProfile(BaseModel):
    horizon_designation: str
    depth_top_cm: float
    depth_bottom_cm: float
    textural_class: str
    clay_percentage: float
    silt_percentage: float
    sand_percentage: float
    bulk_density_g_cm3: float
    porosity_pct: float
    field_capacity_vol_pct: float
    wilting_point_vol_pct: float
    available_water_capacity_mm_cm: float
    hydraulic_conductivity_ksat_mm_hr: float
    ph_water: float
    electrical_conductivity_ds_m: float
    cation_exchange_capacity_cmol_kg: float
    organic_carbon_pct: float
    total_nitrogen_pct: float
    available_p_mehlich3_ppm: float
    exchangeable_k_ppm: float
    base_saturation_pct: float


class BenchmarkSoilSeries(BaseModel):
    series_id: str
    series_name: str
    usda_subgroup: str
    wrb_reference_group: str
    geographical_basin: str
    parent_material: str
    drainage_class: str
    permeability_class: str
    typical_slope_pct: float
    rusle_k_factor: float
    horizons: List[SoilHorizonProfile]
    management_recommendations: List[str]


