def get_benchmark_soil(series_id: str) -> Optional[BenchmarkSoilSeries]:
    return BENCHMARK_SOIL_SERIES.get(series_id)

def list_all_benchmark_soils() -> List[BenchmarkSoilSeries]:
    return list(BENCHMARK_SOIL_SERIES.values())
